def compute(vars):
    value_2017 = vars["v1"]
    value_2016 = vars["v2"]
    minimum_balance = min(value_2017, value_2016)

    return {
        "value": minimum_balance,
        "trace": {
            "value_2017": value_2017,
            "value_2016": value_2016,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
